import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";
const dir = "supabase/migrations";
const files = (await readdir(dir)).filter(f => f.endsWith(".sql")).sort();
let out = "-- aOS — all migrations, concatenated in order.\n" +
  "-- Generated by `npm run db:bundle`. Paste into the Supabase SQL editor and run once.\n" +
  "-- Applying this bypasses the CLI's migration history table, so if you later switch\n" +
  "-- to `db push`, mark these as applied with `supabase migration repair --status applied <version>`.\n\n";
for (const f of files) {
  out += `\n-- ${"=".repeat(70)}\n-- ${f}\n-- ${"=".repeat(70)}\n\n`;
  out += await readFile(path.join(dir, f), "utf8");
  out += "\n";
}
await mkdir("supabase/.temp", { recursive: true });
await writeFile("supabase/.temp/bundle.sql", out);
console.log(`bundled ${files.length} migrations → supabase/.temp/bundle.sql`);
